def is_isomorphic(s, t):
    if len(s) != len(t):
        return False
    s_ke_t = {}
    t_ke_s = {}
    for cs, ct in zip(s, t):
        if cs in s_ke_t and s_ke_t[cs] != ct:
            return False
        if ct in t_ke_s and t_ke_s[ct] != cs:
            return False
        s_ke_t[cs] = ct
        t_ke_s[ct] = cs
    return True
